@prefix : <https://w3id.org/ogc/hosted/seadots/prop-rel/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/reference-cases/windfloat-atlantic/eqrel/reef-biomass-equation> ;
            sh:resultMessage "indexed=true requires toProperty to declare an :Aggregation." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "indexed=true requires toProperty to declare an :Aggregation." ;
                    sh:select """
      PREFIX : <https://w3id.org/ogc/hosted/seadots/prop-rel/>
      SELECT $this ?to WHERE {
        $this :toProperty ?to ; :hasEquationSymbol ?entry .
        ?entry :isIndexed true .
        FILTER NOT EXISTS { ?to :hasAggregation ?a }
      } """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape :IndexedTermShape ;
            sh:value <https://example.org/reference-cases/windfloat-atlantic/eqrel/reef-biomass-equation> ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/reference-cases/windfloat-atlantic/eqrel/reef-biomass-equation> ;
            sh:resultMessage "Every symbol entry's fromProperty must be listed in prov:wasDerivedFrom of toProperty." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "Every symbol entry's fromProperty must be listed in prov:wasDerivedFrom of toProperty." ;
                    sh:select """
      PREFIX :     <https://w3id.org/ogc/hosted/seadots/prop-rel/>
      PREFIX prov: <http://www.w3.org/ns/prov#>
      SELECT $this ?from ?to WHERE {
        $this :toProperty ?to ; :hasEquationSymbol ?entry .
        ?entry :fromProperty ?from .
        FILTER NOT EXISTS { ?to prov:wasDerivedFrom ?from }
      } """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape :ProvClosureShape ;
            sh:value <https://example.org/reference-cases/windfloat-atlantic/eqrel/reef-biomass-equation> ] .

